    if count > D[depot_id]['stage_capacity'] + TOL:
        viol.append((('staging',depot_id),'stage_capacity',count,None,D[depot_id]['stage_capacity'],'reassign buses to other depots'))
# planning budget
planning_cost=sum(S[sid]['open_cost'] for sid,v in open_map.items() if v) + sum(D[stage_map[b]]['stage_cost_per_bus'] for b in B if b in stage_map) + sum(C[cid]['activation_cost'] for cid,v in active_map.items() if v)
if planning_cost > config['planning_budget'] + TOL:
    viol.append((('first-stage','planning_budget'),'budget',planning_cost,None,config['planning_budget'],'reduce shelter openings, staging cost, or contraflow activations'))

# scenario checks
covered.extend([
    ('conservation and inventory','pickup demand balance for evacuees, wheelchair, pets; subset checks'),
    ('time/location/readiness/setup/non-overlap','bus sequencing, closure times, shift limits, boarding bay overlap'),
    ('capacities and scenario derates','bus, corridor, shelter, backup-power, smoke-rating, medical-bed limits'),
    ('reserves/ramps','service floors, shelter-in-place caps, fairness gap'),
    ('objective accounting','recomputed public cost components; no exported objective field to compare')
])

scenario_costs={}
for sp in scenario_rows:
    sid=sp['scenario_id']
    scen=Sc[sid]
    trips=sp['bus_trips']
    # domain and sequence checks
    per_bus=defaultdict(list)
    per_pickup_transport=defaultdict(lambda: {'evacuees':0.0,'wheelchair':0.0,'pets':0.0})
    per_shelter=defaultdict(lambda: {'evacuees':0.0,'wheelchair':0.0,'pets':0.0,'medical':0.0})
    corridor_trip_counts=Counter()
    bus_operating=0.0
    smoke_cost=0.0
    late_cost=0.0

    for tr in trips:
        key=(sid,tr['bus_id'],tr['sequence'])
        # id domains
        for field,dom in [('bus_id',B),('pickup_id',P),('shelter_id',S)]:
            if tr[field] not in dom:
                viol.append((key,f'unknown-{field}',tr[field],None,f'known {field}','fix identifier'))
        if tr['bus_id'] in B and tr['pickup_id'] in P and tr['shelter_id'] in S:
            per_bus[tr['bus_id']].append(tr)
            per_pickup_transport[tr['pickup_id']]['evacuees'] += tr['evacuees']
            per_pickup_transport[tr['pickup_id']]['wheelchair'] += tr['wheelchair']
            per_pickup_transport[tr['pickup_id']]['pets'] += tr['pets']
            per_shelter[tr['shelter_id']]['evacuees'] += tr['evacuees']
            per_shelter[tr['shelter_id']]['wheelchair'] += tr['wheelchair']
            per_shelter[tr['shelter_id']]['pets'] += tr['pets']
            per_shelter[tr['shelter_id']]['medical'] += tr['evacuees'] * P[tr['pickup_id']]['medical_share']
            cid=P[tr['pickup_id']]['corridor_id']
            corridor_trip_counts[cid]+=1
            # trip-level capacity/subset
            if tr['evacuees'] > B[tr['bus_id']]['capacity'] + TOL:
                viol.append((key,'bus_capacity',tr['evacuees'],None,B[tr['bus_id']]['capacity'],'reduce load or use larger bus'))
            if tr['wheelchair'] > B[tr['bus_id']]['wheelchair_slots'] + TOL:
                viol.append((key,'wheelchair_slots',tr['wheelchair'],None,B[tr['bus_id']]['wheelchair_slots'],'reduce wheelchair load or reassign bus'))
            if tr['wheelchair'] > tr['evacuees'] + TOL:
                viol.append((key,'wheelchair-subset',tr['wheelchair'],None,tr['evacuees'],'wheelchair passengers must be a subset of evacuees'))
            if tr['pets'] > tr['evacuees'] + TOL:
                viol.append((key,'pets-subset',tr['pets'],None,tr['evacuees'],'pets must be a subset of evacuees'))
            # late closure
            latest=Imp[(sid,cid)]['latest_safe_departure_min'] + (C[cid]['closure_extension_min'] if active_map[cid] else 0)
            if tr['depart_min'] > latest + TOL:
                viol.append((key,'latest_safe_departure',tr['depart_min'],None,latest,'move the trip earlier or activate/retain more closure extension'))
            # route costs
            smoke_mult=Imp[(sid,cid)]['smoke_risk_multiplier']
            smoke_cost += tr['evacuees'] * config['smoke_exposure_cost_per_person'] * smoke_mult
            late_cost += max(0.0, tr['depart_min'] - Imp[(sid,cid)]['latest_safe_departure_min']) * tr['evacuees'] * config['late_pickup_penalty_per_person_min']
        # numeric signs
        for field in ('sequence','depart_min','evacuees','wheelchair','pets'):
            if tr[field] is None:
                viol.append((key,f'null-{field}',None,None,'non-null','populate field'))
        if tr['sequence'] <= 0 or int(tr['sequence']) "'!= tr['"'sequence']:
            viol.append((key,'sequence-domain',tr['sequence'],None,'positive integer','renumber sequence'))
        for field in ('depart_min','evacuees','wheelchair','pets'):
            if tr[field] < -TOL:
                viol.append((key,f'negative-{field}',tr[field],None,0,'use nonnegative quantity'))

    # bus sequencing / exact arc simulation
    for bus_id,btrips in per_bus.items():
        ordered=sorted(btrips,key=lambda r:r['sequence'])
        seqs=[t['sequence'] for t in ordered]
        if seqs "'!= list(range(1,len(ordered)+1)):
            viol.append(((sid,bus_id),'"'sequence-contiguous',seqs,None,list(range(1,len(ordered)+1)),'use contiguous sequence numbers per bus'))
        current_loc=stage_map[bus_id]
        earliest=scen['warning_time_min'] + D[stage_map[bus_id]]['release_delay_min']
        for i,tr in enumerate(ordered):
            required_depart = earliest + leg_time(current_loc,tr['pickup_id'],sid,tr['pickup_id'],active_map) + board_time(tr['evacuees'], tr['wheelchair'])
            if tr['depart_min'] + TOL < required_depart:
                viol.append(((sid,bus_id,tr['sequence']),'route-timing',tr['depart_min'],None,required_depart,'delay this departure or alter prior arcs/load'))
            # operating time counts both legs + service
            bus_operating += leg_time(current_loc,tr['pickup_id'],sid,tr['pickup_id'],active_map) + board_time(tr['evacuees'], tr['wheelchair'])
            bus_operating += leg_time(tr['pickup_id'],tr['shelter_id'],sid,tr['pickup_id'],active_map) + unload_time(tr['evacuees'])
            earliest = tr['depart_min'] + leg_time(tr['pickup_id'],tr['shelter_id'],sid,tr['pickup_id'],active_map) + unload_time(tr['evacuees'])
            current_loc = tr['shelter_id']
        finish=earliest
        shift_end=scen['warning_time_min'] + D[stage_map[bus_id]]['release_delay_min'] + B[bus_id]['shift_limit_min']
        if finish > shift_end + TOL:
            viol.append(((sid,bus_id),'shift_limit',finish,None,shift_end,'shorten route or reduce waiting/trips'))

    # pickup balances and limits
    unserved={r['pickup_id']:r for r in sp['unserved']}
    sip={r['pickup_id']:r for r in sp['shelter_in_place']}
    for pid in P:
        dem=Dem[(sid,pid)]
        tr=per_pickup_transport[pid]
        ur=unserved[pid]
        sr=sip[pid]
        # row-level subset checks for unserved/sip
        for rowname,row in [('unserved',ur),('shelter_in_place',sr)]:
            if row['wheelchair'] > row['evacuees'] + TOL:
                viol.append(((sid,rowname,pid),'wheelchair-subset',row['wheelchair'],None,row['evacuees'],'wheelchair count must be a subset of evacuees'))
            if row['pets'] > row['evacuees'] + TOL:
                viol.append(((sid,rowname,pid),'pets-subset',row['pets'],None,row['evacuees'],'pet count must be a subset of evacuees'))
            for field in ('evacuees','wheelchair','pets'):
                if row[field] < -TOL:
                    viol.append(((sid,rowname,pid),f'negative-{field}',row[field],None,0,'use nonnegative quantity'))
        for field in ('evacuees','wheelchair','pets'):
            total=tr[field]+ur[field]+sr[field]
            if abs(total - dem[field]) > 1e-5:
                viol.append(((sid,pid),f'demand-balance-{field}',total,None,dem[field],'adjust trips/unserved/shelter-in-place to exactly cover demand'))
        served_frac=(tr['evacuees'] + sr['evacuees'])/dem['evacuees'] if dem['evacuees'] else 1.0
        floor=P[pid]['service_floor']
        if served_frac + TOL < floor:
            viol.append(((sid,pid),'service_floor',served_frac,None,floor,'increase transported or shelter-in-place evacuees'))
        sip_limit=P[pid]['shelter_in_place_limit_fraction'] * dem['evacuees']
        if sr['evacuees'] > sip_limit + 1e-5:
            viol.append(((sid,'shelter_in_place',pid),'shelter-in-place-limit',sr['evacuees'],None,sip_limit,'reduce shelter-in-place quantity or transport more evacuees'))

    # fairness
    served={pid:(per_pickup_transport[pid]['evacuees']+sip[pid]['evacuees'])/Dem[(sid,pid)]['evacuees'] for pid in P}
    hi=[pid for pid,r in P.items() if r['priority_class'] in ('high','medical')]
    lo=[pid for pid,r in P.items() if r['priority_class'] in ('standard','remote')]
    for h in hi:
        for l in lo:
            required=served[l]-config['fairness_gap']
            if served[h] + TOL < required:
                viol.append(((sid,h,l),'fairness_gap',served[h],None,required,'raise service at high/medical site or lower service at comparison site'))

    # pickup boarding bays overlap
    pickup_intervals=defaultdict(list)
    for tr in trips:
        start=tr['depart_min'] - board_time(tr['evacuees'], tr['wheelchair'])
        end=tr['depart_min']
        pickup_intervals[tr['pickup_id']].append((start,end,tr['bus_id'],tr['sequence']))
    for pid,ints in pickup_intervals.items():
        events=[]
        for st,en,bid,seq in ints:
            events.append((st,1,bid,seq))
            events.append((en,-1,bid,seq))
        # end before start at same time to avoid false overlap when one ends exactly as another starts
        events.sort(key=lambda x:(x[0],x[1]))
        cnt=0
        maxcnt=0
        for t,typ,bid,seq in events:
            cnt+=typ
            maxcnt=max(maxcnt,cnt)
        if maxcnt > P[pid]['boarding_bays'] + TOL:
            viol.append(((sid,pid),'boarding_bays',maxcnt,None,P[pid]['boarding_bays'],'stagger departures or reassign trips'))

    # corridor capacities
    for cid,count in corridor_trip_counts.items():
        cap=Imp[(sid,cid)]['capacity_trips'] + (C[cid]['capacity_bonus_trips'] if active_map[cid] else 0)
        if count > cap + TOL:
            viol.append(((sid,cid),'corridor_trip_capacity',count,None,cap,'shift trips to other pickup allocations or activate less-congested corridor treatment'))

    # shelter capacities / derates / backup power / smoke safety
    for sh,agg in per_shelter.items():
        if not open_map.get(sh,False):
            viol.append(((sid,sh),'closed-shelter-used',agg['evacuees'],None,0,'route trips only to open shelters'))
        min_rating=Sc[sid]['min_shelter_smoke_rating']
        if agg['evacuees'] > TOL and S[sh]['smoke_safe_rating'] + TOL < min_rating:
            viol.append(((sid,sh),'smoke-rating',S[sh]['smoke_safe_rating'],None,min_rating,'reroute to smoke-safe shelters for this scenario'))
        if agg['evacuees'] > S[sh]['capacity'] + TOL:
            viol.append(((sid,sh),'shelter_capacity',agg['evacuees'],None,S[sh]['capacity'],'reroute evacuees or open more shelter capacity'))
        if agg['wheelchair'] > S[sh]['wheelchair_capacity'] + TOL:
            viol.append(((sid,sh),'shelter_wheelchair_capacity',agg['wheelchair'],None,S[sh]['wheelchair_capacity'],'reroute wheelchair evacuees'))
        if agg['pets'] > S[sh]['pet_capacity'] + TOL:
            viol.append(((sid,sh),'shelter_pet_capacity',agg['pets'],None,S[sh]['pet_capacity'],'reroute pets'))
        if agg['medical'] > S[sh]['medical_beds'] + 1e-5:
            viol.append(((sid,sh),'medical_beds',agg['medical'],None,S[sh]['medical_beds'],'reroute medically fragile evacuees or open more medical capacity'))
    # medical backup requirement: all transported evacuees from medical pickup sites must go to backup power shelters
    for tr in trips:
        if P[tr['pickup_id']]['priority_class']=='medical' and S[tr['shelter_id']]['backup_power']"'!=1 and tr['"'evacuees']>TOL:
            viol.append(((sid,tr['bus_id'],tr['sequence']),'medical-backup-power',S[tr['shelter_id']]['backup_power'],None,1,'send medical-site evacuees only to backup-power shelters'))

    # objective components recomputation
    unserved_cost=0.0
    sip_cost=0.0
    for pid in P:
        ur=unserved[pid]; sr=sip[pid]
        unserved_cost += config['unserved_penalty_per_person']*(ur['evacuees'] + (config['wheelchair_unserved_multiplier']-1)*ur['wheelchair'] + config['pet_unserved_multiplier']*ur['pets'])
        sip_cost += config['shelter_in_place_penalty_per_person']*(sr['evacuees'])
    scen_cost=bus_operating*1.0  # placeholder to add bus op rate per bus below
    # recompute bus operating with per-bus rates more exactly
    bus_op=0.0
    for bus_id,btrips in per_bus.items():
        ordered=sorted(btrips,key=lambda r:r['sequence'])
        current=stage_map[bus_id]
        for tr in ordered:
            work=leg_time(current,tr['pickup_id'],sid,tr['pickup_id'],active_map)+board_time(tr['evacuees'], tr['wheelchair'])+leg_time(tr['pickup_id'],tr['shelter_id'],sid,tr['pickup_id'],active_map)+unload_time(tr['evacuees'])
            bus_op += work * B[bus_id]['operating_cost_per_min']
            current=tr['shelter_id']
    scenario_costs[sid]={
        'bus_operating_cost':bus_op,
        'smoke_cost':smoke_cost,
        'late_cost':late_cost,
        'unserved_cost':unserved_cost,
        'shelter_in_place_cost':sip_cost,
        'scenario_total':bus_op+smoke_cost+late_cost+unserved_cost+sip_cost,
    }

# Print violations and summary
print('VIOLATION_COUNT', len(viol))
for v in viol[:200]:
    print(v)
print('SCENARIO_COSTS')
for sid in sorted(scenario_costs):
    print(sid, scenario_costs[sid])
# deterministic cost
first_stage=sum(S[s]['open_cost'] for s,v in open_map.items() if v)+sum(D[stage_map[b]]['stage_cost_per_bus'] for b in stage_map)+sum(C[c]['activation_cost'] for c,v in active_map.items() if v)
print('FIRST_STAGE_COST', first_stage)
# risk adjusted objective piece if desired
probs={sid:Sc[sid]['probability'] for sid in Sc}
exp=sum(probs[sid]*scenario_costs[sid]['scenario_total'] for sid in Sc)
alpha=config['tail_risk_alpha']
# CVaR-style surcharge based on weighted scenarios
ordered=sorted(((scenario_costs[sid]['scenario_total'], probs[sid], sid) for sid in Sc), reverse=True)
remaining=1-alpha
cvar_num=0.0
for cost,p,sid in ordered:
    take=min(remaining,p)
    if take>0:
        cvar_num += take*cost
        remaining -= take
if 1-alpha>0:
    cvar=cvar_num/(1-alpha)
else:
    cvar=max(c['scenario_total'] for c in scenario_costs.values())
print('EXPECTED_SCENARIO_COST', exp)
print('TAIL_CVAR', cvar)
print('RISK_ADJUSTED_TOTAL', first_stage + exp + config['tail_risk_weight']*cvar)
